def metrics(rows): # Preserve complete-case statistics for every independent test category.
    error=np.array([r['relative_L2'] for r in rows]);residual=np.array([r['full_equilibrium_relative'] for r in rows]) # Retain raw prediction errors and unreduced free-DOF equilibrium norms.
    return {'cases':len(rows),'mean_relative_L2':float(error.mean()),'median_relative_L2':float(np.median(error)),'max_relative_L2':float(error.max()),'mean_full_equilibrium_relative':float(residual.mean()),'max_full_equilibrium_relative':float(residual.max()),'accepted':sum(r['research_gate_pass'] for r in rows)} # Keep the denominator and all failures explicit.
def complete_metrics(evaluation): # Separate in-range geometry, dimension extrapolation and completely unseen structural type.
    rows=evaluation['cases'];groups={split:metrics([r for r in rows if r['split']==split]) for split in ['test','ood']} # Report both frozen independent physical regimes.
    unseen=[r for r in rows if r.get('unseen_family',False)] # Include every deck geometry excluded from both fitting and validation.
    if unseen:groups['entirely_unseen_structural_type']=metrics(unseen) # Preserve the full unseen-family denominator rather than only favourable cases.
    return groups # Keep aggregate statistics derivable from the complete case records.
