            fine_paths=sorted((RUN/'cases').glob(f'{family}_mesh_*/receipt.json'),key=lambda path:float(path.parent.name.split('_')[-1]));fine=fine_paths[0];receipt=json.loads(fine.read_text());fine_item={'id':receipt['id'],'family':family,'geometry_id':receipt['id'],'split':'unseen_mesh','params':receipt['params']};fine_sample=(enhanced if refined else features)(fine_item) # Build a genuinely different fine-node count without a per-mesh decoder or POD basis.
